insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 16, 'O homem que se afasta do caminho do entendimento repousará no ajuntamento dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 17, 'Quem ama o prazer sofrerá necessidade; aquele que ama o vinho e o azeite nunca enriquecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 18, 'O resgate [em troca] do justo é o perverso; e no lugar do reto [fica] o transgressor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 19, 'É melhor morar em terra deserta do que com uma mulher briguenta e que se irrita facilmente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 20, '[Há] tesouro desejável e azeite na casa do sábio; mas o homem tolo é devorador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 21, 'Quem segue a justiça e a bondade achará vida, justiça e honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 22, 'O sábio passa por cima da cidade dos fortes e derruba a fortaleza em que confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 23, 'Quem guarda sua boca e sua língua guarda sua alma de angústias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 24, '“Zombador” é o nome do arrogante e orgulhoso; ele trata [os outros] com uma arrogância irritante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 25, 'O desejo do preguiçoso o matará, porque suas mãos se recusam a trabalhar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 26, 'Ele fica desejando suas cobiças o dia todo; mas o justo dá, e não deixa de dar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 27, 'O sacrifício dos perversos é abominável; quanto mais quando a oferta é feita com má intenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 28, 'A testemunha mentirosa perecerá; porém o homem que ouve [a verdade] falará com sucesso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 29, 'O homem perverso endurece seu rosto, mas o correto confirma o seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 30, 'Não há sabedoria, nem entendimento, nem conselho contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 31, 'O cavalo é preparado para o dia da batalha, mas a vitória [vem] do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 1, 'É preferível ter um [bom] nome do que muitas riquezas; e ser favorecido é melhor que a prata e o o ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 2, 'O rico e o pobre se encontram; todos eles foram feitos pelo SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 3, 'O prudente vê o mal, e se esconde; mas os ingênuos passam e sofrem as consequências.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 4, 'A recompensa da humildade [e do] temor ao SENHOR são riquezas, honra, e vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 5, '[Há] espinhos e ciladas no caminho do perverso; quem cuida de sua alma deve ficar longe de [tal caminho] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 6, 'Instrui ao menino em seu caminho, e até quando envelhecer, não se desviará dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 7, 'O rico domina sobre os pobres, e quem toma emprestado é servo daquele que empresta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 8, 'Aquele que semeia perversidade colherá sofrimento; e a vara de sua ira se acabará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 9, 'Quem tem olhos bondosos será abençoado, porque deu de seu pão ao pobre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 10, 'Expulsa ao zombador, e a briga terminará; cessará a disputa e a vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 11, 'Quem ama a pureza do coração [fala] graciosamente com os lábios, [e] o rei [será] seu amigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 12, 'Os olhos do SENHOR protegem o conhecimento; porém ele transtornará as palavras do enganador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 13, 'O preguiçoso diz: Há um leão lá fora! Ele me matará nas ruas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 14, 'A boca da mulher pervertida é uma cova profunda; aquele contra quem o SENHOR se irar cairá nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 15, 'A tolice está amarrada ao coração do menino; [mas] a vara da correção a mandará para longe dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 16, 'Aquele que oprime ao pobre para proveito próprio e aquele que dá [suborno] ao rico certamente empobrecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 17, 'Inclina o teu ouvido e escuta as palavras dos sábios; dispõe teu coração ao meu conhecimento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 18, 'porque é agradável que as guardes dentro de ti, e estejam prontas para os teus lábios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 19, 'para que tua confiança esteja no SENHOR, eu as ensino a ti hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 20, 'Por acaso não te escrevi excelentes coisas sobre o conselho e o conhecimento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 21, 'para te ensinar a certeza das palavras da verdade, para que possas responder palavras de verdade aos que te enviarem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 22, 'Não roubes ao pobre, porque ele é pobre; nem oprimas ao aflito junto à porta do julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 23, 'Porque o SENHOR defenderá a causa deles em juízo, e quanto aos que os roubam, ele lhes roubará a alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 24, 'Não seja companheiro de quem se irrita facilmente, nem andes com o homem furioso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 25, 'Para que não aprendas o caminho dele, e te ponhas em armadilhas para tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 26, 'Não estejas entre os que se comprometem em acordos com as mãos, [ou] os que ficam por fiadores de dívidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 27, 'Se não tens como pagar, por que razão tirariam tua cama debaixo de ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 28, 'Não mudes os limites antigos que teus pais fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 22, 29, 'Viste um homem habilidoso em sua obra? Perante a face dos reis ele será posto; ele não será posto diante de pessoas sem honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 1, 'Quando te sentares para comer com algum dominador, presta muita atenção para o que estiver diante de ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 2, 'E põe uma faca à tua garganta, se tiveres muito apetite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 3, 'Não desejes as comidas gostosas dele, porque são pão de mentiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 4, 'Não trabalhes exaustivamente para ser rico; modera-te por meio de tua prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 5, 'Porás teus olhos fixos sobre aquilo que é nada? Porque certamente se fará asas, e voará ao céu como uma águia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 6, 'Não comas o pão de quem tem olho maligno, nem cobices suas comidas gostosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 7, 'Porque ele calcula [seus gastos] consigo mesmo. Assim ele dirá: Come e bebe; Mas o coração dele não está contigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 8, 'Vomitarias o pedaço que comeste, e perderias tuas palavras agradáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 9, 'Não fales aos ouvidos do tolo, porque ele desprezará a prudência de tuas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 10, 'Não mudes os limites antigos, nem ultrapasses as propriedades dos órfãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 11, 'Porque o Defensor deles é poderoso; ele disputará a causa deles contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 12, 'Aplica teu coração à disciplina, e teus ouvidos às palavras de conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 13, 'Não retires a disciplina do jovem; quando lhe bateres com a vara, nem [por isso] morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 14, 'Tu lhe baterás com a vara, e livrarás a sua alma do Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 15, 'Meu filho, se teu coração for sábio, meu coração se alegrará, e eu também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 16, 'Meu interior saltará de alegria quando teus lábios falarem coisas corretas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 17, 'Teu coração não inveje aos pecadores; porém [permanece] no temor ao SENHOR o dia todo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 18, 'Porque certamente há um [bom] futuro [para ti] , e tua expectativa não será cortada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 19, 'Ouve, filho meu, e sê sábio; e conduz teu coração no caminho [correto] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 20, 'Não esteja entre os beberrões de vinho, [nem] entre os comilões de carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 21, 'Porque o beberrão e o comilão empobrecerão; e a sonolência os faz vestir trapos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 22, 'Ouve a teu pai, que te gerou; e não desprezes a tua mãe, quando ela envelhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 23, 'Compra a verdade, e não a vendas; [faze o mesmo com] a sabedoria, a disciplina e a prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 24, 'O pai do justo muito se alegrará; aquele que gerar o sábio se encherá de alegria por causa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 25, 'Teu pai e tua mãe se alegrarão; aquela te te gerou se encherá de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 26, 'Meu filho, dá para mim teu coração, e que teus olhos prestem atenção em meus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 27, 'Porque a prostituta é [como] uma cova profunda, e a estranha [como] um poço estreito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 28, 'Também ela fica espreitando como um ladrão, e acrescenta transgressores entre os homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 29, 'De quem são os ais? De quem são os sofrimentos? De quem são as lutas? De quem são as queixas? De quem são as feridas desnecessárias? De quem são os olhos vermelhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 30, 'São daqueles que gastam tempo junto ao vinho, daqueles que andam em busca da bebida misturada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 31, 'Não prestes atenção ao vinho quando se mostra vermelho, quando brilha no copo e escorre suavemente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 32, '[Pois] seu fim é [como] mordida de cobra, e picará como uma víbora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 33, 'Teus olhos verão [coisas] estranhas, e teu coração falará perversidades;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 34, 'E serás como o que dorme no meio do mar, e como o que dorme no topo do mastro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 23, 35, '[E dirás] : Espancaram-me, mas não senti dor; bateram em mim, mas não senti; quando virei a despertar? Vou buscar mais uma [bebida] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 1, 'Não tenhas inveja dos homens malignos, nem desejes estar com eles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 2, 'Porque o coração deles imagina destruição, e os lábios deles falam de opressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 3, 'Pela sabedoria a casa é edificada, e pelo entendimento ela fica firme;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 4, 'E pelo conhecimento os cômodos se encherão de riquezas preciosas e agradáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 5, 'O homem sábio é poderoso; e o homem que tem conhecimento aumenta [sua] força;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 6, 'Porque com conselhos prudentes farás tua guerra; e a vitória [é alcançada] pela abundância de conselheiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 7, 'A sabedoria é alta demais para o tolo; na porta [do julgamento] ele não abre sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 8, 'Quem planeja fazer o mal será chamado de vilão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 9, 'O pensamento do tolo é pecado; e o zombador é abominável aos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 10, '[Se] te mostrares fraco no dia da angústia, como é pouca tua força!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 11, 'Livra os que estão tomados para a morte, os que estão sendo levados para serem mortos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 12, 'Pois se tu disseres: Eis que não sabíamos,Por acaso aquele que pesa os corações não saberá? Aquele que guarda tua alma não conhecerá? Ele retribuirá ao homem conforme sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 13, 'Come mel, meu filho, porque é bom; e o favo de mel é doce ao teu paladar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 14, 'Assim será o conhecimento da sabedoria para tua alma; se a encontrares haverá recompensa [para ti] ; e tua esperança não será cortada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 15, 'Tu, perverso, não espies a habitação do justo, nem assoles seu quarto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 16, 'Porque o justo cai sete vezes, e se levanta; mas os perversos tropeçam no mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 17, 'Quando teu inimigo cair, não te alegres; nem teu coração fique contente quando ele tropeçar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 18, 'Para que não [aconteça] de o SENHOR veja, e o desagrade, e desvie dele sua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 19, 'Não te irrites com os malfeitores, nem tenhas inveja dos perversos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 20, 'Porque o maligno não terá um bom futuro; a lâmpada dos perversos se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 21, 'Meu filho, teme ao SENHOR e ao rei; e não te envolvas com os rebeldes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 22, 'Porque a destruição deles se levantará de repente; e quem sabe que ruína eles terão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 23, 'Estes [provérbios] também são para os sábios: fazer acepção de pessoas num julgamento não é bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 24, 'Aquele que disser ao ímpio: Tu és justo,Os povos o amaldiçoarão, as nações o detestarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 25, 'Mas para aqueles que [o] repreenderem, haverá coisas boas; e sobre eles virá uma boa bênção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 26, 'Quem responde palavras corretas é [como se] estivesse beijando com os lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 27, 'Prepara o teu trabalho de fora, e deixa pronto o teu campo; então depois, edifica a tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 28, 'Não sejas testemunha contra o teu próximo sem causa; por que enganarias com teus lábios?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 29, 'Não digas: Assim como ele fez a mim, assim também farei a ele; pagarei a cada um conforme sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 30, 'Passei junto ao campo do preguiçoso, e junto à vinha do homem sem juízo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 31, 'e eis que ela estava toda cheia de espinheiros, [e] sua superfície coberta de urtigas; e o seu muro de pedras estava derrubado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 32, 'Quando eu vi [isso] , aprendi em meu coração, e, olhando, recebi instrução:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 33, 'um pouco de sono, cochilando um pouco, cruzando as mãos por um pouco de tempo, deitado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 24, 34, 'e assim a tua pobreza virá como um assaltante; a tua necessidade, como um homem armado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 1, 'Estes também são provérbios de Salomão, que foram copiados pelos homens de Ezequias, rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 2, 'É glória de Deus encobrir alguma coisa; mas a glória dos Reis é investigá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 3, 'Para a altura dos céus, para a profundeza da terra, assim como para o coração dos reis, não há como serem investigados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 4, 'Tira as escórias da prata, e sairá um vaso para o fundidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 5, 'Tira o perverso de diante do rei, e seu trono se firmará com justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 6, 'Não honres a ti mesmo perante o rei, nem te ponhas no lugar dos grandes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 7, 'Porque é melhor que te digam: Sobe aqui;Do que te rebaixem perante a face do príncipe, a quem teus olhos viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 8, 'Não sejas apressado para entrar numa disputa; senão, o que farás se no fim teu próximo te envergonhar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 9, 'Disputa tua causa com teu próximo, mas não reveles segredo de outra pessoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 10, 'Para que não te envergonhe aquele que ouvir; pois tua má fama não pode ser desfeita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 11, 'A palavra dita em tempo apropriado é [como] maçãs de ouro em bandejas de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 12, 'O sábio que repreende junto a um ouvido disposto a escutar é [como] pendentes de ouro e ornamentos de ouro refinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 13, 'Como frio de neve no tempo da colheita, [assim] é o mensageiro fiel para aqueles que o enviam; porque ele refresca a alma de seus senhores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 14, '[Como] nuvens e ventos que não trazem chuva, [assim] é o homem que se orgulha de falsos presentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 15, 'Com paciência para não se irar é que se convence um líder; e a língua suave quebra ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 16, 'Achaste mel? Come o que te for suficiente; para que não venhas a ficar cheio demais, e vomites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 17, 'Não exagere teus pés na casa de teu próximo, para que ele não se canse de ti, e te odeie.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 18, 'Martelo, espada e flecha afiada é o homem que fala falso testemunho contra seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 19, 'Confiar num infiel no tempo de angústia é [como] um dente quebrado ou um pé sem firmeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 20, 'Quem canta canções ao coração aflito é como aquele que tira a roupa num dia frio, ou como vinagre sobre salitre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 21, 'Se aquele que te odeia tiver fome, dá-lhe pão para comer; e se tiver sede, dá-lhe água para beber;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 22, 'Porque [assim] amontoarás brasas sobre a cabeça dele, e o SENHOR te recompensará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 23, 'O vento norte traz a chuva; [assim como] a língua caluniadora [traz] a ira no rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 24, 'É melhor morar num canto do terraço do que com uma mulher briguenta numa casa espaçosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 25, '[Como] água refrescante para a alma cansada, assim são boas notícias de uma terra distante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 26, 'O justo que se deixa levar pelo perverso é [como] uma fonte turva e um manancial poluído.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 27, 'Comer muito mel não é bom; assim como buscar muita glória para si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 25, 28, 'O homem que não pode conter seu espírito é [como] uma cidade derrubada sem muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 1, 'Assim como a neve no verão, como a chuva na colheita, assim também não convém a honra para o tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 2, 'Como um pássaro a vaguear, como a andorinha a voar, assim também a maldição não virá sem causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 3, 'Açoite para o cavalo, cabresto para o asno; e vara para as costas dos tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 4, 'Não respondas ao tolo conforme sua loucura; para que não te faças semelhante a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 5, 'Responde ao tolo conforme sua loucura, para que ele não seja sábio aos seus próprios olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 6, 'Quem manda mensagens pelas mãos do tolo é como quem corta os pés e bebe violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 7, '[Assim] como não funcionam as pernas do aleijado, assim também é o provérbio na boca dos tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 8, 'Dar honra ao tolo é como amarrar uma pedra numa funda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 9, 'Como espinho na mão do bêbado, assim é o provérbio na boca dos tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 10, '[Como] um flecheiro que atira para todo lado, [assim] é aquele que contrata um tolo [ou] que contrata alguém que vai passando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 11, 'Como um cão que volta a seu vômito, [assim] é o tolo que repete sua loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 12, 'Viste algum homem sábio aos seus próprios olhos? Mais esperança há para o tolo do que para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 13, 'O preguiçoso diz: Há uma fera no caminho; há um leão nas ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 14, '[Como] a porta se vira em torno de suas dobradiças, [assim] o preguiçoso [se vira] em sua cama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 15, 'O preguiçoso põe sua mão no prato, e acha cansativo demais trazê-la de volta a sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 16, 'O preguiçoso se acha mais sábio aos próprios olhos do que sete que respondem com prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 17, 'Aquele que, enquanto está passando, [se envolve] em briga que não é sua, é [como] o que pega um cão pelas orelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 18, 'Como o louco que lança faíscas, flechas e coisas mortíferas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 19, 'Assim é o homem que engana a seu próximo, e diz: Não estava eu [só] brincando?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 20, 'Sem lenha, o fogo se apaga; e sem fofoqueiro, a briga termina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 21, 'O carvão é para as brasas, e a lenha para o fogo; e o homem difamador para acender brigas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 22, 'As palavras do fofoqueiro são como alimentos deliciosos, que descem ao interior do ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 23, 'Como um vaso de fundição coberto de restos de prata, [assim] são os lábios inflamados e o coração maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 24, 'Aquele que odeia dissimula em seus lábios, mas seu interior abriga o engano;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 25, 'Quando ele [te] falar agradavelmente com sua voz, não acredites nele; porque há sete abominações em seu coração;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 26, 'Cujo ódio está encoberto pelo engano; sua maldade será descoberta na congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 27, 'Quem cava uma cova, nela cairá; e quem rola uma pedra, esta voltará sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 26, 28, 'A língua falsa odeia aos que ela atormenta; e a boca lisonjeira opera ruína.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 1, 'Não te orgulhes do dia de amanhã; porque não sabes o que o dia trará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 2, 'Que o estranho te louve, e não tua [própria] boca; o estrangeiro, e não teus [próprios] lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 3, 'A pedra é pesada, e a areia tem [seu] peso; mas a provocação do tolo é mais pesada do que estas ambas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 4, 'O furor é cruel, e a ira impetuosa; mas quem resistirá firme perante à inveja?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 5, 'Melhor é a repreensão clara do que o amor escondido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 6, 'Fiéis são as feridas [feitas] por um amigo, mas os beijos de um inimigo são enganosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 7, 'A alma saciada rejeita o favo de mel; mas para a alma faminta, toda coisa amarga é doce.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 8, 'Como a ave, que vagueia de seu ninho, assim é o homem que anda vagueando de seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 9, 'O óleo e o perfume alegram ao coração; assim é a doçura de um amigo com um conselho sincero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 10, 'Não abandones o teu amigo, nem o amigo de teu pai; nem entres na casa de teu irmão no dia de tua adversidade; melhor é o vizinho que está perto do que o irmão que está longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 11, 'Sê sábio, meu filho, e alegra meu coração; para que eu tenha algo a responder para aquele que me desprezar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 12, 'O prudente vê o mal, [e] se esconde; [mas] os ingênuos passam adiante, e sofrem as consequências.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 13, 'Toma a roupa daquele que fica por fiador de estranho; toma penhor daquele [que fica por fiador] da estranha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 14, 'Aquele que bendiz ao seu amigo em alta voz durante a madrugada lhe será considerado como maldição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 15, 'A mulher briguenta é semelhante a uma goteira contínua em tempo de grande chuva;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 16, 'Tentar contê-la é como tentar conter o vento, ou impedir que o óleo escorra de sua mão direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 17, 'O ferro é afiado com ferro; assim também o homem afia o rosto de seu amigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 18, 'Aquele que guarda a figueira comerá de seu fruto; e o que dá atenção ao seu senhor será honrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 19, 'Assim como a água reflete o rosto, assim também o coração reflete o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 20, 'O Xeol e a perdição nunca estão saciados; assim também os olhos do homem nunca estão satisfeitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 21, '[Como] o crisol é para a prata, e o forno para o ouro, assim o homem [é provado] pelos louvores que lhe dizem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 22, 'Ainda que esmagues ao tolo em um pilão junto com os grãos, ainda assim sua loucura não se separaria dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 23, 'Procura conhecer a condição de tuas ovelhas; põe teu coração sobre o gado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 24, 'porque o tesouro não [dura] para sempre; nem uma coroa [dura] de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 25, 'Quando a erva aparecer, e surgirem a folhagem, e se juntarem as ervas dos montes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 26, 'Os cordeiros serão para tuas roupas, e os bodes para o preço do campo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 27, 27, 'E o leite das cabras será o suficiente para tua alimentação, para a alimentação de tua casa, e para o sustento de tuas servas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 1, 'Os perversos fogem [mesmo] quando não há quem os persiga, mas os justos são confiantes como um leão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 2, 'Pela rebelião numa terra, seus governantes são muitos; mas por meio de um homem prudente e conhecedor [seu governo] permanecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 3, 'O homem pobre que oprime aos necessitados é [como] uma chuva devastadora [que causa] falta de pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 4, 'Os que abandonam a lei louvam ao perverso; porém os que guardam a lei lutarão contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 5, 'Os homens maus não entendem a justiça; mas os que buscam ao SENHOR entendem tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 6, 'Melhor é o pobre que anda em sua honestidade do que o perverso de caminhos, ainda que seja rico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 7, 'O que guarda a lei é um filho prudente, mas o companheiro de comilões envergonha a seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 8, 'Aquele que aumenta seus bens por meio de juros e lucros desonestos está juntando para o que se compadece dos pobres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 9, 'Aquele que desvia seus ouvidos de ouvir a lei, até sua oração [será] abominável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 10, 'Aquele que faz as pessoas corretas errarem em direção a um mau caminho, ele mesmo cairá em sua cova; mas os que não tiverem pecado herdarão o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 11, 'O homem rico é sábio aos seus [próprios] olhos; mas o pobre prudente o examina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 12, 'Quando os justos estão contentes, muita é a alegria; mas quando os perversos se levantam, os homens se escondem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 13, 'Quem encobre suas transgressões nunca prosperará, mas aquele que as confessa e [as] abandona alcançará misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 14, 'Bem-aventurado o homem que sempre mantém seu temor; mas aquele que endurece seu coração cairá no mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 15, 'Leão rugidor e urso faminto é o governante perverso sobre um povo pobre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 16, 'O príncipe que tem falta de entendimento aumenta as opressões; mas aquele que odeia o lucro desonesto prolongará [seus] dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 17, 'O homem atormentado pelo sangue de alguma alma fugirá até a cova; ninguém o detenha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 18, 'Aquele que anda sinceramente será salvo; mas o que se desvia em [seus] caminhos cairá de uma só vez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 19, 'Aquele que lavrar sua terra terá fartura de pão; mas o que segue coisas inúteis terá fartura de pobreza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 20, 'O homem fiel [terá] muitas bênçãos; mas o que se apressa para enriquecer não ficará impune.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 21, 'Fazer acepção de pessoas não é bom; porque até por um pedaço de pão o homem pode transgredir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 22, 'Quem tem pressa para ter riquezas é um homem de olho mau; e ele não sabe que a miséria virá sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 23, 'Aquele que repreende ao homem obterá mais favor depois do que aquele que lisonjeia com a língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 24, 'Aquele que furta seu pai ou sua mãe e diz: Não é pecado,É companheiro do homem destruidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 25, 'Quem tem alma orgulhosa levanta brigas; mas aquele que confia no SENHOR prosperará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 26, 'Aquele que confia em seu [próprio] coração é tolo; mas o que anda em sabedoria escapará [em segurança] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 27, 'Quem dá ao pobre não terá falta; mas o que esconde seus olhos [terá] muitas maldições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 28, 28, 'Quando os perversos ganham poder, os homens se escondem; mas quando perecem, os justos se multiplicam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 1, 'O homem que age com teimosia, mesmo depois de muitas repreensões, será tão destruído que não terá mais cura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 2, 'Quando os justos se engrandecem, o povo se alegra; mas quando o perverso domina, o povo geme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 3, 'O homem que ama a sabedoria alegra a seu pai; mas o companheiro de prostitutas gasta os bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 4, 'O rei por meio da justiça firma a terra; mas o amigo de subornos a transtorna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 5, 'O homem que lisonjeia a seu próximo arma uma rede para seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 6, 'Na transgressão do homem mau há uma armadilha; mas o justo se alegra e se enche de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 7, 'O justo considera a causa judicial dos pobres; [mas] o perverso não entende [este] conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 8, 'Homens zombadores trazem confusão a cidade; mas os sábios desviam a ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 9, 'O homem sábio que disputa no julgamento contra um tolo, mesmo se perturbado ou rindo, não terá descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 10, 'Homens sanguinários odeiam o honesto; mas os corretos procuram o seu bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 11, 'O louco mostra todo o seu ímpeto; mas o sábio o mantém sob controle.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 12, 'O governante que dá atenção a palavras mentirosas, todos os seus servos serão perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 13, 'O pobre e o enganador se encontram: o SENHOR ilumina aos olhos de ambos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 14, 'O rei que julga aos pobres por meio da verdade, seu trono se firmará para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 15, 'A vara e a repreensão dão sabedoria; mas o rapaz deixado solto envergonha a sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 16, 'Quando os perversos se multiplicam, multiplicam-se as transgressões; mas os justos verão sua queda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 17, 'Castiga a teu filho, e ele te fará descansar, e dará prazeres à tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 18, 'Não havendo visão profética, o povo fica confuso; porém o que guarda a lei, ele é bem-aventurado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 19, 'O servo não será corrigido por meio de palavras; porque [ainda que] entenda, mesmo assim ele não responderá [corretamente] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 20, 'Viste um homem precipitado em suas palavras? Mais esperança há para um tolo do que para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 21, 'Aquele que mima a seu servo desde a infância, por fim ele quererá ser [seu] filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 22, 'O homem que se irrita facilmente levanta brigas; e o furioso multiplica as transgressões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 23, 'A arrogância do homem o abaterá; mas o humilde de espírito obterá honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 24, 'Aquele que reparte com o ladrão odeia sua [própria] alma; ele ouve maldições e não [o] denuncia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 25, 'O temor do homem arma ciladas; mas o que confia no senhor ficará em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 26, 'Muitos buscam a face do governante; mas o julgamento de cada um [vem] do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 29, 27, 'O justos odeiam ao homem perverso; e o injusto odeia aos que andam no caminho correto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 1, 'Palavras de Agur, filho de Jaque, o de fala solene; [Este] homem diz a Itiel; a Itiel e a Ucal:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 2, 'Certamente eu sou o mais bruto dos homens, e não tenho entendimento humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 3, 'Não aprendi sabedoria, nem tenho conhecimento do Santo [Deus] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 4, 'Quem subiu ao céu, e desceu? Quem juntou os ventos com suas mãos? Quem amarrou as águas numa capa? Quem estabeleceu todos os limites da terra? Qual é o seu nome? e qual é o nome de seu filho, se tu o sabes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 5, 'Toda palavra de Deus é pura; é escudo para os que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 6, 'Nada acrescentes às suas palavras, para que ele não te repreenda, e sejas mostrado como mentiroso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 7, 'Duas coisas eu te pedi; não [as] negues a mim antes que eu morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 8, 'Afasta de mim a inutilidade e palavra mentirosa; [e] não me dês nem pobreza nem riqueza, mantém-me com o pão que me for necessário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 9, 'Para que não aconteça de eu ficar farto e [te] negar, dizendo: Quem é o SENHOR?Nem também que eu empobreça, e venha a furtar, e desonre o nome do meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 10, 'Não difames do servo ao seu senhor, para que ele não te amaldiçoe e fiques culpado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 11, 'Há gente que amaldiçoa a seu pai e não bendiz à sua mãe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 12, 'Há gente que é pura aos seus [próprios] olhos, mas que não foi lavada de sua imundície;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 13, 'Há gente cujos olhos são arrogantes, e cujas sobrancelhas são levantadas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 14, 'Há gente cujos dentes são espadas, e cujos queixos são facas, para devorarem aos aflitos da terra aos aflitos, e aos necessitados dentre os homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 15, 'A sanguessuga tem duas filhas: “Dá” e “Dá”; estas três coisas nunca se fartam, e quatro nunca dizem “É o suficiente”:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 16, 'O Xeol, o útero estéril, a terra que não se farta de água, e o fogo que nunca diz estar satisfeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 17, 'Os olhos que zombam do pai ou desprezam obedecer à mãe, os corvos do riacho os arrancarão, e os filhotes de abutre os comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 18, 'Estas três coisas me maravilham, e quatro que não entendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 19, 'O caminho da águia no céu, o caminho da serpente na rocha, o caminho do navio no meio do mar, e o caminho do homem com uma moça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 20, 'Assim é o caminho da mulher adúltera: ela come, limpa sua boca, e diz: Não fiz mal algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 21, 'Por três coisas a terra se alvoroça, e por quatro que não pode suportar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 22, 'Pelo servo que governa como rei; [pelo] tolo que se enche de comida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 23, 'Pela mulher odiada, quando se casa; e [pela] serva quando toma o lugar de sua senhora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 24, 'Estas quatro coisas são pequenas sobre a terra, porém muito sábias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 25, 'As formigas não são criaturas fortes, mas no verão preparam sua comida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 26, 'Os roedores são um “povo” fraco, mas fazem suas casas nas rochas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 27, 'Os gafanhotos não têm rei; mas todos saem em bandos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 28, 'As lagartixas podem ser pegas com as mãos, e mesmo assim estão nos palácios dos reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 29, 'Estes três tem um bom andar, e quatro que se movem muito bem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 30, 'O leão, forte entre os animais, que não foge de ninguém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 31, 'O galo, o bode, e o rei com seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 32, 'Se agiste como tolo, exaltando-te, e se planejaste o mal, [põe tua] mão sobre a boca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 30, 33, 'Porque [como] o forçar do leite produz manteiga, e o forçar do nariz produz sangue, [assim também] o forçar da ira produz briga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 1, 'Palavras do rei Lemuel, a profecia que sua mãe o ensinava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 2, 'O que [posso te dizer] ,meu filho, ó filho do meu ventre? O que [te direi] ,filho de minhas promessas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 3, 'Não dês tua força às mulheres, nem teus caminhos para [coisas] que destroem reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 4, 'Lemuel, não convém aos reis beber vinho; nem aos príncipes [desejar] bebida alcoólica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 5, 'Para não acontecer de que bebam, e se esqueçam da lei, e pervertam o direito de todos os aflitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 6, 'Dai bebida alcoólica aos que estão a ponto de morrer, e vinho que têm amargura na alma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 7, 'Para que bebam, e se esqueçam de sua pobreza, e não se lembrem mais de sua miséria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 8, 'Abre tua boca no lugar do mudo pela causa judicial de todos os que estão morrendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 9, 'Abre tua boca, julga corretamente, e faze justiça aos oprimidos e necessitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 10, 'Mulher virtuosa, quem a encontrará? Pois seu valor é muito maior que o de rubis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 11, 'O coração de seu marido confia nela, e ele não terá falta de bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 12, 'Ela lhe faz bem, e não o mal, todos os dias de sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 13, 'Ela busca lã e linho, e com prazer trabalha com suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 14, 'Ela é como um navio mercante; de longe traz a sua comida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 15, 'Ainda de noite ela se levanta, e dá alimento a sua casa; e ordens às suas servas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 16, 'Ela avalia um campo, e o compra; do fruto de suas mãos planta uma vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 17, 'Ela prepara seus lombos com vigor, e fortalece seus braços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 18, 'Ela prova que suas mercadorias são boas, [e] sua lâmpada não se apaga de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 19, 'Ela estende suas mãos ao rolo de linha, e com suas mãos prepara os fios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 20, 'Ela estende sua mão ao aflito, e estica os braços aos necessitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 21, 'Ela não terá medo da neve por sua casa, pois todos os de sua casa estão agasalhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 22, 'Ela faz cobertas para sua cama; de linho fino e de púrpura é o seu vestido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 23, 'Seu marido é famoso às portas [da cidade] ,quando ele se senta com os anciãos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 24, 'Ela faz panos de linho fino, e os vende; e fornece cintos aos comerciantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 25, 'Força e glória são suas roupas, e ela sorri pelo seu futuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 26, 'Ela abre sua boca com sabedoria; e o ensinamento bondoso está em sua língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 27, 'Ela presta atenção aos rumos de sua casa, e não come pão da preguiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 28, 'Seus filhos se levantam e a chamam de bem-aventurada; seu marido também a elogia, [dizendo] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 29, 'Muitas mulheres agem com virtude, mas tu és melhor que todas elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 30, 'A beleza é enganosa, e a formosura é passageira; [mas] a mulher que teme ao SENHOR, essa será louvada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 31, 31, 'Dai a ela conforme o fruto de suas mãos, e que suas obras a louvem às portas [da cidade] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 1, 'Palavras do Pregador, filho de Davi, rei em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 2, 'Futilidade das futilidades! - diz o Pregador - futilidade das futilidades! Tudo é fútil!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 3, 'Que proveito tem o homem de todo o seu trabalho que ele trabalha abaixo do sol?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 4, 'Geração vai, e geração vem; porém a terra permanece para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 5, 'O sol nasce, e o sol se põe; e se apressa ao seu lugar onde nasceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 6, 'O vento vai ao sul, e rodeia para o norte; continuamente o vento vai rodeando e voltando aos lugares onde circulou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 7, 'Todos os rios vão para o mar, e contudo o mar não se enche; ao lugar onde os ribeiros correm, para ali eles voltam a correr.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 8, 'Todas [estas] coisas são [tão] cansativas, que ninguém consegue descrever; os olhos não ficam satisfeitos de ver, nem os ouvidos se enchem de ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 9, 'O que foi, isso será; e o que se fez, isso será feito; de modo que nada há de novo abaixo do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 10, 'Existe algo que se possa dizer: Vê isto, que é novo?Isso já existia nos tempos passados, que foram antes de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 11, 'Não há lembrança das coisas que já aconteceram; e das coisas que vão acontecer, também delas não haverá lembrança entre aqueles que vierem depois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 12, 'Eu o Pregador, me tornei rei sobre Israel em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 13, 'E dei meu coração a investigar e pesquisar com sabedoria sobre tudo o que acontece abaixo do céu; esta cansativa ocupação Deus deu aos filhos dos homens, para que nela fossem forçados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 14, 'Vi todas as obras que são feitas abaixo do sol, e eis que tudo é futilidade e aflição de espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 15, 'O que é torto não pode ser endireitado; o que está em falta não pode ser contado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 16, 'Eu falei ao meu coração, dizendo: Eis que eu me tornei grande, e aumentei em sabedoria, sobre todos os que tinham sido antes de mim em Jerusalém; e meu coração experimentou uma abundância de sabedoria e conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 17, 'E dei meu coração para entender sabedoria, e para entender loucuras e tolices; e percebi que também isto era aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 1, 18, 'Porque na muita sabedoria há muito aborrecimento, e aquele que aumenta em conhecimento aumenta em angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 1, 'Disse eu em meu coração: Vamos! Eu te provarei com alegria, por isso dá atenção ao que é bom! Porém eis que isto também era futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 2, 'Eu disse ao riso: Estás doido; e à alegria: De que esta serve?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 3, 'Decidi como experiência entregar minha carne ao vinho (guiando porém meu coração com sabedoria) e praticar a loucura, para eu ver o que era melhor aos filhos dos homens fazerem abaixo do céu durante os dias de suas vidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 4, 'Fiz para mim obras grandiosas; construí casas para mim; plantei vinhas para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 5, 'Fiz para mim pomares e jardins; e plantei neles árvores de toda [espécie de] frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 6, 'Fiz para mim tanques de águas, para regar com eles o bosque em que se plantavam as árvores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 7, 'Adquiri escravos e escravas, e tive [escravos] nascidos em casa; também tive grande rebanho de vacas e ovelhas, mais do que todos os que houve antes de mim em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 8, 'Também juntei para mim prata, ouro, e tesouros de reis e de províncias; reservei para mim cantores e cantoras, e dos prazeres dos filhos dos homens: várias mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 9, 'Então me engrandeci e aumentei, mais do que todos quantos houve antes de mim em Jerusalém; além disto minha sabedoria ficou comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 10, 'E tudo quanto meus olhos desejaram, eu não lhes neguei; nem privei meu coração de alegria alguma, pois meu coração se alegrou de todo o meu trabalho; e esta foi minha parte [que obtive] de todo o meu trabalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 11, 'E eu olhei para todas as obras que minhas mãos fizeram, como também para o trabalho ao qual me dispus a trabalhar; e eis que tudo era fútil [como] perseguir o vento, e que não havia proveito algum abaixo do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 12, 'Então passei a observar a sabedoria, as loucuras e a tolice; porque o que o homem pode fazer depois do rei, que já não tenha sido feito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 13, 'Então eu vi que a sabedoria é melhor do que a tolice, assim como a luz é melhor do que as trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 14, 'Os olhos do sábio estão em sua cabeça, mas o tolo anda em trevas; então eu também entendi que o mesmo futuro acontece a todos eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 15, 'Por isso eu disse em meu coração: Assim como acontece ao tolo, também acontecerá a mim; por que então eu me tornei mais sábio? Então disse em meu coração que isto também era inútil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 16, 'Porque não haverá lembrança para sempre, nem do sábio, nem do tolo; porque de tudo quanto agora há, nos dias futuros será esquecido; e o sábio morre assim como o tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 17, 'Por isso detestei a vida, porque a obra que é feita abaixo do sol me faz sofrer; pois tudo é fútil [como] perseguir o vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 18, 'Eu também detestei todo o meu trabalho em que trabalhei abaixo do sol, porque o deixarei ao homem que virá depois de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 19, 'Pois quem sabe se ele será sábio ou tolo? Contudo ele terá controle de todo o meu trabalho em que trabalhei, e que sabiamente conduzi abaixo do sol; também isso é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 20, 'Por isso eu fiz meu coração perder a esperança de todo o meu trabalho em que trabalhei abaixo do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 21, 'Porque há [um tipo de] homem que trabalha com sabedoria, conhecimento e habilidade; porém deixará tudo como herança a um [outro] homem que não trabalhou naquilo; também isto é fútil e muito desagradável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 22, 'Pois que [proveito] o homem tem por todo o seu trabalho e cansaço de seu coração em que ele trabalha abaixo do sol?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 23, 'Porque todos os seus dias são dores, e aflição [é] sua rotina; até de noite seu coração não descansa; também isto é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 24, 'Não há nada melhor ao homem do que comer, beber, e fazer sua alma se alegrar de seu trabalho; eu também vi que isto vem da mão de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 25, '(Pois quem [melhor] comeria ou teria pressa, a não ser eu mesmo?)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 2, 26, 'Porque ao homem bom perante sua face, [Deus] dá sabedoria, conhecimento e alegria; porém ao pecador ele dá trabalho cansativo, para juntar e recolher, para o dar ao bom diante da sua face; também isto é fútil [como] perseguir o vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 1, 'Para todas as coisas há um tempo determinado, e todo propósito abaixo do céu [tem seu] tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 2, 'Tempo de nascer e tempo de morrer; tempo de plantar e tempo de arrancar o que foi plantado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 3, 'Tempo de matar e tempo de curar; tempo de derrubar e tempo de construir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 4, 'Tempo de chorar e tempo de rir; tempo de lamentar, e tempo de saltar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 5, 'Tempo de espalhar pedras e tempo de juntar pedras; tempo de abraçar e tempo de evitar abraçar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 6, 'Tempo de buscar e tempo de perder; tempo de guardar e tempo de jogar fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 7, 'Tempo de rasgar e tempo de costurar; tempo de ficar calado e tempo de falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 8, 'Tempo de amar e tempo de odiar; tempo de guerra e tempo de paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 9, 'Que proveito tem o trabalhador naquilo em que ele trabalha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 10, 'Tenho visto a ocupação que Deus deu aos filhos dos homens, para com ela os manter ocupados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 11, 'Tudo ele fez belo ao seu tempo; também pôs a sensação de eternidade no coração deles, sem que o homem consiga entender a obra que Deus fez, desde o princípio até o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 12, 'Tenho percebido que não há coisa melhor para eles do que se alegrarem e fazerem o bem em suas vidas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 13, 'E também que todo homem coma, beba e fique contente com todo o seu trabalho; [isto] é um presente de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 14, 'Eu sei que tudo quanto Deus faz durará para sempre; a isso nada será acrescentado e nada será diminuído; e Deus faz [assim] para que haja temor perante sua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 15, 'O que tem sido agora, já foi antes; e o que vier a ser [também] já foi; Deus busca [de volta] o que foi passado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 16, 'Vi mais abaixo do sol: que no lugar do juízo havia ali perversidade; e que no lugar da justiça havia ali perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 17, 'Eu disse em meu coração: Deus julgará ao justo e ao perverso, porque ali há tempo para todo propósito e para toda obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 18, 'Eu disse em meu coração quanto aos filhos dos homens, que Deus lhes provaria, para lhes mostrar que eles são como animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 19, 'Porque o que acontece aos filhos dos homens, isso mesmo também acontece aos animais; o mesmo acontece a eles [todos] ; assim como um morre, assim também morre o outro; e todos tem uma mesma respiração; e a vantagem dos homens sobre os animais é nenhuma, pois todos são fúteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 20, 'Todos vão a um [mesmo] lugar; todos vieram do pó [da terra] , e todos voltarão ao pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 21, 'Quem tem certeza de que o fôlego de vida dos homens sobe para cima, e que o fôlego de vida dos animais desce para debaixo da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 3, 22, 'Por isso tenho visto que não há coisa melhor do que o homem se alegrar de suas obras, porque essa é a parte que lhe pertence; pois quem pode levá-lo a ver o que será depois de sua [morte] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 1, 'Depois me virei, e observei todas as opressões que são feitas abaixo do sol; e eis que [vi] as lágrimas dos oprimidos, que não tinham consolador; a força estava do lado dos seus opressores, porém eles não tinham quem os consolasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 2, 'Por isso eu considerei os mortos, que já morreram, serem mais merecedores de elogios do que os vivos, que ainda vivem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 3, 'E melhor que estes ambos, é aquele que ainda não existe; que não viu as más obras, que são feitas abaixo do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 4, 'Também vi eu que todo o trabalho, e toda a habilidade em obras, [causa] ao homem a inveja de seu próximo; também isto é fútil [como] perseguir o vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 5, 'O tolo junta suas mãos, e come sua [própria] carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 6, 'É melhor uma mão cheia [com] descanso, do que ambas as mãos cheias [com] trabalho e perseguição ao vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 7, 'Então eu me voltei, e vi uma futilidade abaixo do sol:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 8, 'Havia um que era sozinho, sem filho, nem irmão; e seu trabalho não tem fim, nem seus olhos se fartam de riquezas; nem [diz] : Para quem estou trabalhando, e privando minha alma do que é bom? Também isso é futilidade e enfadonha ocupação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 9, 'Dois são melhores do que um, porque eles têm melhor recompensa por seu trabalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 10, 'Porque se vierem a cair, um levanta ao seu companheiro; mas ai daquele que está só, pois caso caia, não há outro que o levante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 11, 'Também, se dois se deitarem juntos, eles se aquecem; mas como alguém sozinho poderá se aquecer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 12, 'E se alguém prevalecer contra um, dois podem resistir contra ele; porque o cordão de três dobras não se rompe tão depressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 13, 'Melhor é o jovem pobre e sábio do que o rei velho e tolo, que não sabe dar ouvidos aos conselhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 14, 'porque esse [jovem] pode sair até da prisão para se tornar rei, ainda que tenha nascido pobre em seu reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 15, 'Vi todos os vivos, que andam abaixo do sol, estarem com o jovem, o sucessor, que ficaria em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 4, 16, 'Não havia fim todo o povo, todo o que houve antes deles; porém os que vêm depois não se alegrarão nele. Também isso é fútil [como] perseguir o vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 1, 'Guarda os teus passos quando entrares na casa de Deus, e te achegues a ouvir em vez de oferecer sacrifícios de tolos, pois não sabem que fazem mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 2, 'Não te precipites com tua boca, nem te apresses com teu coração, a pronunciar palavra alguma perante a face de Deus; porque Deus está nos céus, e tu estás na terra; por isso, que tuas palavras sejam poucas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 3, 'Pois, como os sonhos vêm das muitas ocupações, assim também o excesso de palavras vem da voz do tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 4, 'Quando fizeres algum voto a Deus, não demores em pagá-lo; porque ele não se agrada de tolos. Paga o voto que fizeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 5, 'Melhor é que não faças voto, do que fazeres um voto, e não o pagares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 6, 'Não permitas que a tua boca faça a tua carne pecar; nem digas perante o mensageiro que foi um mero erro; por que provocarias a ira de Deus com a tua voz, para que ele destrua a obra de tuas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 7, 'Porque, como na abundância de sonhos há futilidades, assim, também, há abundância de palavras; tu, porém, teme a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 8, 'Se vires em algum território a opressão dos pobres, e a violência contra o direito e a justiça, não te surpreendas de tal caso; porque o oficial tem uma autoridade maior que o supervisiona; e acima de ambos há outros que têmautoridade ainda maior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 9, 'E o proveito da terra é para todos; até o rei se serve do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 10, 'O que amar o dinheiro nunca se saciará do dinheiro; e quem amar a riqueza, nunca [se saciará] do lucro; isso também é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 11, 'Onde os bens se multiplicam, ali se multiplicam também os que os cosomem; e que proveito pois tem seus donos, a não ser somente ver [as riquezas] com seus próprios olhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 12, 'Doce é o sono do trabalhador, quer coma pouco, quer muito; porém a fartura do rico não o deixa dormir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 13, 'Há um mal causador de sofrimentos que vi abaixo do sol: as riquezas que seus donos guardam para seu próprio mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 14, 'Porque as mesmas riquezas se perdem com negócios malsucedidos; e quando gera algum filho, nada lhe fica em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 15, 'Assim como ele saiu do ventre de sua mãe, nu ele voltará, indo-se como veio; e nada tomará de seu trabalho, que possa levar em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 16, 'De maneira que isto também é um mal causador de sofrimentos, que exatamente como veio, assim se vai; e que proveito ele teve em trabalhar para o vento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 17, 'Além disso, ele comeu em trevas todos os seus dias; sofreu muito, e teve enfermidades e irritações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 18, 'Eis o que eu vi, algo bom e belo: comer, beber, e experimentar o que é bom de todo o seu trabalho em que trabalhou abaixo do sol, durante os dias de sua vida, que Deus lhe deu; porque isto é a parte que lhe pertence.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 19, 'E todo homem a quem Deus deu riquezas e bens, e lhe deu poder para comer delas, e tomar sua parte, e se alegrar de seu trabalho; isto é presente de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 5, 20, 'Pois ele não se lembrará muito dos dias de sua vida, porque Deus lhe responde com alegria de seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 1, 'Há um mal que vi abaixo do sol, e é muito frequente entre os homens:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 2, 'Um homem a quem Deus deu riquezas, bens, e honra; e nada lhe falta de tudo quanto a sua alma deseja; porém Deus não lhe dá poder para dessas coisas comer; em vez disso, um estranho as come; isso é futilidade e um mal causador de sofrimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 3, 'Se o homem gerar cem [filhos] , e viver muitos anos, e os dias de seus anos forem muitos, porém se sua alma não se saciar daquilo que é bom, nem tiver sepultamento, digo que ter sido abortado [teria sido] melhor para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 4, 'Pois veio em futilidade, e se vai em trevas; e nas trevas seu nome é encoberto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 5, '[Alguém] que nunca tivesse visto o sol, nem [o] conhecido, teria mais descanso do que ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 6, 'E ainda que vivesse mil anos duas vezes, e não experimentasse o que é bom, por acaso não vão todos para o mesmo lugar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 7, 'Todo o trabalho do homem é para sua boca; porém sua alma nunca se satisfaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 8, 'Pois que vantagem tem o sábio sobre o tolo? E que [mais] tem o pobre que sabe como se comportar diante dos vivos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 9, 'Melhor é a vista dos olhos do que o vaguear da cobiça; também isto é fútil [como] perseguir o vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 10, 'Seja o que for, seu nome já foi chamado; e [já] se sabe o que o homem é; e que não pode disputar contra aquele que é mais poderoso do que ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 11, 'Pois quanto mais palavras há, maior é a futilidade; e que proveito há [nelas] para o homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 6, 12, 'Pois quem sabe o que é bom nesta vida para o homem, durante os dias de sua vida de futilidade, os quais ele gasta como sombra? Pois quem contará ao homem o que haverá depois dele abaixo do sol?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 1, 'Melhor é uma boa reputação do que o bom óleo perfumado; e o dia da morte [é melhor] que o dia de seu nascimento'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 2, 'Melhor é ir à casa do luto do que a casa do banquete, [porque] isto é o fim de todos os homens; e os vivos tomam isto em seus corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 3, 'Melhor é o sofrimento do que o riso, porque com a tristeza do rosto o coração se aperfeiçoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 4, 'O coração dos sábios está na casa do luto, mas o coração dos tolos [está] na casa da alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 5, 'Melhor é ouvir a repreensão do sábio do que alguém ouvir a canção dos tolos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 6, 'Pois o riso dos tolos é como o ruído de espinhos debaixo de uma panela; também isto é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 7, 'Verdadeiramente a opressão faz até o sábio enlouquecer, e o suborno corrompe o coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 8, 'Melhor é o fim das coisas do que o princípio delas; melhor é o paciente de espírito do que o arrogante de espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 9, 'Não te apresses em teu espírito para te irares, porque a ira repousa no colo dos tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 10, 'Nunca digas: Por que os dias passados foram melhores que os atuais? Pois nunca com sabedoria perguntarias isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 11, 'A sabedoria é tão boa quanto uma herança; ela é um proveito para os que veem a luz do sol;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 12, 'porque a sabedoria serve de proteção, assim como o dinheiro serve de proteção; mas a vantagem do conhecimento é que a sabedoria dá vida ao seu dono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 13, 'Observa a obra de Deus, pois quem poderá endireitar o que ele entortou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 14, 'No dia da prosperidade, alegra-te; mas no dia da adversidade, considera; pois Deus faz um em contraposição ao outro, para que o homem não consiga descobrir o que haverá depois dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 15, 'Tudo [isto] vi nos meus dias de futilidade: há justo que perece em sua justiça, e há perverso que prolonga [sua vida] em sua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 16, 'Não sejas justo demais, nem sejas sábio demais; para que destruirias a ti mesmo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 17, 'Não sejas perverso demais, nem sejas tolo; para que morrerias antes de teu tempo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 18, 'É bom que retenhas isto, e também não retires tua mão disto, pois quem teme a Deus escapa de tudo isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 19, 'A sabedoria fortalece ao sábio, mais do que dez homens de autoridade que estejam na cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 20, 'Verdadeiramente não há homem justo sobre a terra, que faça o bem, e nunca peque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 21, 'Além disso, não dês atenção a todas as palavras que forem ditas, para que não venhas a ouvir que teu servo te amaldiçoa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 22, 'Pois teu coração sabe que também tu já amaldiçoaste a outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 23, 'Tudo isto investiguei com sabedoria. Eu disse: Terei para mim mais sabedoria;porém ela ficava [ainda] mais longe de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 24, 'Quem pode encontrar o que está distante e tão profundo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 25, 'Decidi em meu coração conhecer, investigar e buscar a sabedoria e a razão; e saber o mal que há na tolice e na loucura das maluquices.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 26, 'E eu encontrei uma coisa mais amarga que a morte: a mulher cujo coração são redes e armadilhas, e suas mãos são amarras; quem for bom perante Deus escapará dela; mas o pecador ficará preso nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 27, 'Olha isto:(diz o pregador, enquanto ele procurava entender [as coisas] ,uma por uma)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 28, 'Aquilo que minha alma tem buscado, ainda não achei; um homem entre mil eu achei; mas uma mulher entre todas estas não achei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 7, 29, 'Eis que somente achei isto: que Deus fez os homens corretos, porém foram eles que buscaram muitos desejos ruins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 1, 'Quem é semelhante ao sábio? E quem sabe a interpretação das coisas? A sabedoria do homem faz seu rosto brilhar, e a dureza de seu rosto é alterada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 2, 'Eu digo: obedece às ordens do rei, por causa do juramento [que fizeste] a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 3, 'Não te apresses de sair da presença dele, nem persistas em alguma coisa má; pois tudo que ele deseja, ele faz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 4, 'Naquilo que há a palavra do rei, ali há autoridade; e quem lhe dirá: O que estás fazendo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 5, 'Quem obedecer ao mandamento não experimentará mal algum; e o coração do sábio sabe a hora e a maneira [corretas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 6, 'Porque para todo propósito há uma hora e uma maneira [correta] ; por isso o mal do homem é muito sobre ele:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 7, 'Pois ele não sabe o que irá acontecer. Quem pode lhe avisar o que vai acontecer, e quando?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 8, 'Não há homem nenhum que tenha domínio sobre o espírito, para reter ao espírito; nem [tem] domínio sobre dia da morte, nem meios de escapar d [esta] guerra; nem a perversidade livrará a seus donos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 9, 'Tudo isto vi quando fiz coração considerar toda obra que se faz abaixo do sol: há um tempo em que um homem passa a dominar [outro] homem, para sua [própria] ruína.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 10, 'Também assim vi os perversos sepultados, e vinham, e saíam do lugar santo; e eles foram esquecidos na cidade em que assim fizeram; isso também é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 11, 'Dado que o julgamento pela obra má não é feito imediatamente, por causa disso o coração dos filhos dos homens está cheio [de vontade] neles, para fazer o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 12, 'Ainda que um pecador faça o mal cem vezes e [sua vida] se prolongue, mesmo assim eu sei, que as coisas boas acontecerão aos que temem a Deus, aos que temerem diante da sua face.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 13, 'Porém ao perverso não sucederá o bem, e não prolongará [seus] dias, [que serão] como uma sombra, pois ele não tem temor diane de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 14, 'Há [outra] futilidade que é feita sobre a terra: que há justos a quem acontece conforme as obras dos perversos, e há perversos a quem acontece conforme as obras dos justos. Digo que isso também é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 15, 'Assim elogiei a alegria, pois o homem não tem nada melhor abaixo do sol do que comer, beber e se alegrar; que isso acompanhe seu trabalho nos dias de sua vida, que Deus lhe dá abaixo do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 16, 'Enquanto entregava meu coração a entender a sabedoria, e ver a ocupação que é feita abaixo do sol (ainda que nem de dia, nem de noite, [o homem] veja sono em seus olhos),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 8, 17, 'Então vi toda a obra de Deus, que o homem não pode compreender a obra que é feita abaixo do sol; mesmo que o homem trabalhe para a buscar, ele não a encontrará; ainda que o sábio diga que a conhece, ele não pode compreendê [-la] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 1, 'Por isso fiz meu coração considerar todas estas coisas, para entender com clareza tudo isto: que os justos, e os sábios, e suas obras, estão nas mãos de Deus; até o amor e o ódio, o homem nada sabe o que há à sua frente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 2, 'Tudo [acontece] de modo semelhante a todos; o mesmo acontece ao justo e ao perverso; ao bom e ao puro, assim como ao impuro; tanto ao que sacrifica, como ao que não sacrifica; tanto ao bom, como ao pecador; ao que jura, assim como ao que teme [fazer] juramento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 3, 'Esta coisa má [existe] entre tudo o que é feito abaixo do sol, que a todos aconteça o mesmo; e que o coração dos filhos homens esteja cheio de maldade, e que haja loucuras em seus corações durante suas vidas, e depois [eles vão] para entre os mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 4, 'Porque para aquele que está junto a todos os vivos há esperança (pois melhor é um cão vivo do que um leão morto).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 5, 'Porque os vivos sabem que vão morrer; mas os mortos não sabem coisa alguma, nem também tem mais recompensa; pois a lembrança deles já foi esquecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 6, 'Até seu amor, até seu ódio, e até sua inveja já pereceu e nenhuma parte nunca mais lhes pertence, em tudo quanto se faz abaixo do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 7, 'Vai, come com alegria teu pão, e bebe com bom coração o teu vinho; pois Deus se agrada de tuas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 8, 'Em todo tempo sejam brancas as tuas roupas, e nunca falte óleo sobre tua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 9, 'Aproveite a vida com a mulher que tu amas, todos os dias da tua fútil vida, que [Deus] te deu abaixo do sol, todos os teus fúteis dias; porque esta é a parte que te pertence nesta vida e em teu trabalho no qual trabalhaste abaixo do sol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 10, 'Tudo quanto vier à tua mão para fazer, faze conforme as tuas forças; porque no Xeol, para onde vais, não há trabalho, nem planos, nem conhecimento, nem sabedoria alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 11, 'Voltei-me, e vi abaixo do sol, que a corrida não é dos velozes, nem dos guerreiros a batalha, nem dos sábios o pão, nem dos prudentes as riquezas, nem dos conhecedores o favor; mas que o tempo e a ocasião imprevista acontece a todos estes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 12, 'Porque também o homem não sabe seu tempo, assim como os peixes que são capturados pela maligna rede; e como os passarinhos que são presos na armadilha; assim também os filhos dos homens são pegos pelo tempo mau, quando cai de repente sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 13, 'Também vi esta sabedoria abaixo do sol, que considerei grande:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 14, '[Havia] uma pequena cidade, em que havia poucas pessoas; e veio contra ela um grande rei, e a cercou, e levantou contra ela grandes barreiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 15, 'E se achou nela um homem pobre sábio, que livrou aquela cidade com sua sabedoria; porém ninguém se lembrou daquele pobre homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 16, 'Então eu disse: Melhor é a sabedoria do que a força; ainda que a sabedoria do pobre tenha sido desprezada, e suas palavras não tenham sido ouvidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 17, 'As palavras dos sábios devem ser ouvidas em quietude, mais do que o grito daquele que domina sobre os tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 9, 18, 'Melhor é a sabedoria do que as armas de guerra; porém um só pecador destrói muitas coisas boas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 1, '[Assim como] as moscas mortas fazem cheirar mal do óleo do perfumador, [assim também] um pouco de tolice se sobrepõe à sabedoria e honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 2, 'O coração do sábio [está] à sua direita; mas o coração do tolo [está] à sua esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 3, 'E até quando o tolo vai pelo caminho, falta-lhe [bom-senso em seu] coração, e diz a todos que é ele é tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 4, 'Se o espírito de um chefe se levantar contra ti, não deixes teu lugar, porque a calma aquieta grandes ofensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 5, 'Há um mal que vi abaixo do sol, um [tipo de] erro que é proveniente dos que têm autoridade:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 6, 'Põem o tolo em cargos elevados, mas os ricos sentam em lugares baixos.')
